INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,route_name,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time,update_by,update_time,remark) SELECT '期货品种',@p,8,'varieties','future/catalog','FutureVarieties',1,0,'C','0','0','future:history:list','list','admin',NOW(),'admin',NOW(),'t_future_variety' WHERE NOT EXISTS(SELECT 1 FROM sys_menu WHERE parent_id=@p AND path='varieties');
