INSERT INTO sys_role_menu(role_id,menu_id) SELECT 1,menu_id FROM sys_menu WHERE parent_id=@p AND path IN('varieties','variety-plates','main-index') AND NOT EXISTS(SELECT 1 FROM sys_role_menu x WHERE x.role_id=1 AND x.menu_id=sys_menu.menu_id);
